source("config.R")
# ================================================================
# Figure S1 | Robustness of Physical and Information Networks
# FULL PERIOD: 2011-2023 | TN / TP | no FDR
# Uses the ACTUAL Fusion_Net_2011_2023 (with underscore) folder.
# It does not require a separate TE CSV: Fusion_all_pairs_layers.csv
# stores full-pair TE_raw / p_value generated by the original script.
# ================================================================

pkgs <- c('readr','dplyr','tidyr','ggplot2','patchwork','scales','stringr')
for (p in pkgs) if (!requireNamespace(p,quietly=TRUE)) install.packages(p)
invisible(lapply(pkgs,library,character.only=TRUE))

ROOT <- get_data_root()
FUSION_ROOT <- file.path(ROOT,'Fusion_Net_2011_2023')
PNET_ROOT <- file.path(ROOT,'PNet_2011_2023_BlockTracing')
OUT <- file.path(ROOT,'Figure_S1_fullperiod_clean')
dir.create(OUT,recursive=TRUE,showWarnings=FALSE)

ALPHA <- 0.10
QS <- c(.60,.70,.75,.80,.85,.90)
COLORS <- c(TN='#327FA6',TP='#E18652')

id8 <- function(x) {
  x <- trimws(as.character(x)); x <- sub('\\.0+$','',x)
  bad <- is.na(x)|x %in% c('','NA','NaN')
  x[bad] <- NA_character_
  good <- !bad & grepl('^[0-9]{1,8}$',x)
  x[good] <- stringr::str_pad(x[good],8,pad='0')
  x
}

require_file <- function(x) {
  if (!file.exists(x)) stop('Missing input: ',x,call.=FALSE)
  x
}

pick_col <- function(nms,options,label,required=TRUE) {
  found <- options[options %in% nms]
  if (length(found)) return(found[[1]])
  if (required) stop(label,': no field matching ',paste(options,collapse='/'),
                     '\nActual fields: ',paste(nms,collapse=', '),call.=FALSE)
  NA_character_
}

check_pairs <- function(d,label) {
  if(anyNA(d$from)|anyNA(d$to)|any(d$from==d$to))
    stop(label,': invalid source/target IDs',call.=FALSE)
  if(anyDuplicated(d[c('from','to')])) stop(label,': duplicated directed pairs',call.=FALSE)
  invisible(TRUE)
}

# P-Net matrix: support (1) long from/to/R columns, or (2) square wide
# matrices with row station ID and column station IDs.
# Missing cells stay NA. Do not turn NA into zero.
read_reach <- function(path,ids,nu) {
  d <- readr::read_csv(require_file(path),
                       col_types=readr::cols(.default=readr::col_character()),show_col_types=FALSE)
  nms <- names(d)
  fc <- pick_col(nms,c('from','source','upstream','STAID_from'),'reach from',FALSE)
  tc <- pick_col(nms,c('to','target','downstream','STAID_to'),'reach to',FALSE)
  rc <- pick_col(nms,c('R','reachable','reachability','is_reachable','R_phys'),'reach status',FALSE)
  
  if (!is.na(fc) && !is.na(tc) && !is.na(rc)) {
    x <- tibble::tibble(from=id8(d[[fc]]),to=id8(d[[tc]]),raw_R=d[[rc]])
  } else {
    rowc <- nms[[1]]
    x <- d |>
      dplyr::rename(from=dplyr::all_of(rowc)) |>
      tidyr::pivot_longer(-from,names_to='to',values_to='raw_R') |>
      dplyr::mutate(from=id8(from),to=id8(to))
  }
  
  z <- tolower(trimws(as.character(x$raw_R)))
  x$R <- dplyr::case_when(
    z %in% c('1','1.0','true','t','yes','reachable') ~ 1L,
    z %in% c('0','0.0','false','f','no','non-reachable','unreachable') ~ 0L,
    TRUE ~ NA_integer_
  )
  x <- x |>
    dplyr::filter(from %in% ids,to %in% ids,from!=to) |>
    dplyr::select(from,to,R)
  if (anyDuplicated(x[c('from','to')])) stop(nu,': repeated reachability pairs',call.=FALSE)
  x
}

read_full <- function(nu) {
  folder <- file.path(FUSION_ROOT,nu)
  layer_path <- file.path(folder,'Fusion_all_pairs_layers.csv')
  weight_path <- file.path(folder,'Fusion_display_all_edges.csv')
  reach_path <- file.path(PNET_ROOT,nu,'PNet_reachability_matrix.csv')
  
  layers <- readr::read_csv(require_file(layer_path),
                            col_types=readr::cols(from=readr::col_character(),to=readr::col_character(),
                                                  .default=readr::col_guess()),show_col_types=FALSE)
  cat('\n',nu,' layers: ',paste(names(layers),collapse=', '),'\n',sep='')
  needed <- c('from','to','TE_raw','p_value')
  if (length(setdiff(needed,names(layers))))
    stop(nu,': fusion full layers lack ',paste(setdiff(needed,names(layers)),collapse=', '),
         '\nCannot reconstruct S1(a) without all candidate p-values.',call.=FALSE)
  
  te <- layers |>
    dplyr::transmute(from=id8(from),to=id8(to),
                     TE=pmax(0,as.numeric(TE_raw)),p=as.numeric(p_value))
  check_pairs(te,paste(nu,'TE layers'))
  ids <- sort(unique(c(te$from,te$to)))
  if (nrow(te)!=length(ids)*(length(ids)-1L))
    stop(nu,': Fusion_all_pairs_layers is NOT a complete directed candidate-pair table',call.=FALSE)
  if (anyNA(te$p)) stop(nu,': p_value contains NA; cannot calculate whole-network TE counts',call.=FALSE)
  if (any(!is.finite(te$TE))) stop(nu,': invalid TE weights',call.=FALSE)
  
  w <- readr::read_csv(require_file(weight_path),
                       col_types=readr::cols(from=readr::col_character(),to=readr::col_character(),
                                             .default=readr::col_guess()),show_col_types=FALSE)
  wc <- pick_col(names(w),c('W_fus','W_fusion','fusion_weight','weight'),'Fusion weight')
  w <- tibble::tibble(from=id8(w$from),to=id8(w$to),W=as.numeric(w[[wc]]))
  check_pairs(w,paste(nu,'display weights'))
  if (!setequal(paste(te$from,te$to),paste(w$from,w$to)))
    stop(nu,': full layers and displayed Fusion use different node/pair sets',call.=FALSE)
  
  r <- read_reach(reach_path,ids,nu)
  d <- te |>
    dplyr::left_join(w,by=c('from','to')) |>
    dplyr::left_join(r,by=c('from','to')) |>
    dplyr::mutate(nutrient=nu)
  if(anyNA(d$W)|any(!is.finite(d$W))|any(d$W<0))
    stop(nu,': incomplete / invalid full-period Fusion weights',call.=FALSE)
  cat(sprintf('%s: %d nodes, %d pairs | R=1 %d | R=0 %d | R=? %d\n',
              nu,length(ids),nrow(d),sum(d$R==1,na.rm=TRUE),
              sum(d$R==0,na.rm=TRUE),sum(is.na(d$R))))
  d
}

all <- dplyr::bind_rows(lapply(c('TN','TP'),read_full))
readr::write_csv(all |> dplyr::count(nutrient,R,name='n_pairs'),
                 file.path(OUT,'00_physical_status_QA.csv'))

# (a) TE-significance sensitivity: raw p only (no FDR)
a <- dplyr::bind_rows(lapply(c('TN','TP'), function(nu) {
  d_nu <- dplyr::filter(all, .data$nutrient == .env$nu)
  tibble::tibble(
    nutrient = nu,
    alpha = c(.05,.10),
    n_edges = vapply(c(.05,.10), function(a0) as.integer(sum(d_nu$p < a0)), integer(1))
  )
})) |>
  dplyr::mutate(criterion=factor(sprintf('p < %.2f',alpha),levels=c('p < 0.05','p < 0.10')))
readr::write_csv(a,file.path(OUT,'s1a_TE_significance.csv'))
p_a <- ggplot2::ggplot(a,ggplot2::aes(criterion,n_edges,fill=nutrient))+
  ggplot2::geom_col(position=ggplot2::position_dodge(width=.74),width=.65)+
  ggplot2::geom_text(ggplot2::aes(label=n_edges),
                     position=ggplot2::position_dodge(width=.74),vjust=-.3,size=3.3)+
  ggplot2::scale_fill_manual(values=COLORS)+
  ggplot2::scale_y_continuous(expand=ggplot2::expansion(mult=c(0,.12)))+
  ggplot2::labs(title='(a) TE significance sensitivity',x=NULL,y='Significant directed TE edges',fill=NULL)

# (b) TE strength ONLY for confirmed R=1 or R=0, significant and positive.
b_all <- all |> dplyr::filter(p<ALPHA,TE>0)
b <- b_all |> dplyr::filter(!is.na(R)) |>
  dplyr::mutate(group=factor(ifelse(R==1,'Reachable','Non-reachable'),
                             levels=c('Reachable','Non-reachable')))
b_stats <- b |> dplyr::group_by(nutrient,group) |>
  dplyr::summarise(n=dplyr::n(),median=stats::median(TE),.groups='drop')
b_unknown <- b_all |> dplyr::group_by(nutrient) |>
  dplyr::summarise(n_unknown=sum(is.na(R)),n_significant=dplyr::n(),.groups='drop')
readr::write_csv(b_stats,file.path(OUT,'s1b_group_stats.csv'))
readr::write_csv(b_unknown,file.path(OUT,'s1b_unknown_QA.csv'))
lab_b <- b_stats |>
  dplyr::mutate(label=paste0('n=',n,'; med=',sprintf('%.3f',median)))
p_b <- ggplot2::ggplot(b,ggplot2::aes(group,TE,fill=group))+
  ggplot2::geom_boxplot(width=.55,outlier.shape=NA,alpha=.62,na.rm=TRUE)+
  ggplot2::geom_jitter(width=.16,height=0,alpha=.13,size=.65,colour='#52616C')+
  ggplot2::geom_text(data=lab_b,ggplot2::aes(x=group,y=Inf,label=label),
                     inherit.aes=FALSE,vjust=1.4,size=2.6)+
  ggplot2::facet_wrap(~nutrient,scales='free_y')+
  ggplot2::scale_fill_manual(values=c('Reachable'='#61A0A5','Non-reachable'='#B3BEC7'))+
  ggplot2::labs(title='(b) TE strength by confirmed physical reachability',
                subtitle='Unknown physical pairs excluded; see QA table',x=NULL,
                y='Bias-corrected TE strength (nats)')+
  ggplot2::theme(legend.position='none')

# (c) 3 different denominators; show confirmed and Unknown separately.
calc_support <- function(d,nu) {
  sig <- d |> dplyr::filter(p<ALPHA,TE>0)
  groups <- list(
    'Candidate pairs'=list(x=d,wt=rep(1,nrow(d))),
    'Significant TE edges'=list(x=sig,wt=rep(1,nrow(sig))),
    'Significant TE strength'=list(x=sig,wt=sig$TE)
  )
  dplyr::bind_rows(lapply(names(groups),function(name){
    z<-groups[[name]]; total<-sum(z$wt)
    tibble::tibble(nutrient=nu,metric=name,n_pairs=nrow(z$x),
                   confirmed_pct=if(total>0)100*sum(z$wt[z$x$R==1],na.rm=TRUE)/total else NA_real_,
                   unknown_pct=if(total>0)100*sum(z$wt[is.na(z$x$R)])/total else NA_real_)
  }))
}
c_dat <- dplyr::bind_rows(lapply(c('TN','TP'),function(nu)
  calc_support(dplyr::filter(all,nutrient==nu),nu))) |>
  dplyr::mutate(metric=factor(metric,levels=c('Candidate pairs','Significant TE edges','Significant TE strength')))
readr::write_csv(c_dat,file.path(OUT,'s1c_physical_support.csv'))
c_long <- c_dat |> tidyr::pivot_longer(c(confirmed_pct,unknown_pct),
                                       names_to='status',values_to='pct') |>
  dplyr::mutate(status=factor(status,levels=c('confirmed_pct','unknown_pct'),
                              labels=c('Confirmed reachable','Unknown status')))
p_c <- ggplot2::ggplot(c_long,ggplot2::aes(metric,pct,fill=nutrient))+
  ggplot2::geom_col(position=ggplot2::position_dodge(width=.7),width=.63)+
  ggplot2::geom_text(ggplot2::aes(label=sprintf('%.1f',pct)),
                     position=ggplot2::position_dodge(width=.7),vjust=-.25,size=2.6)+
  ggplot2::facet_grid(status~.,scales='free_y')+
  ggplot2::scale_fill_manual(values=COLORS)+
  ggplot2::scale_y_continuous(expand=ggplot2::expansion(mult=c(0,.18)))+
  ggplot2::labs(title='(c) Physical support and unresolved statuses',
                subtitle='Different denominators; Unknown is not R = 0',
                x=NULL,y='Percentage (%)')+
  ggplot2::theme(axis.text.x=ggplot2::element_text(angle=18,hjust=1))

# (d) Positive Fusion weights only; report retained n and unknown %.
d_dat <- dplyr::bind_rows(lapply(c('TN','TP'),function(nu){
  dd <- dplyr::filter(all,nutrient==nu,is.finite(W),W>0)
  if(!nrow(dd)) stop(nu,': no positive Fusion weights')
  dplyr::bind_rows(lapply(QS,function(q){
    cut <- as.numeric(stats::quantile(dd$W,probs=q,names=FALSE))
    sub <- dplyr::filter(dd,W>=cut)
    tibble::tibble(nutrient=nu,quantile=q,threshold=cut,n_retained=nrow(sub),
                   confirmed_pct=100*sum(sub$R==1,na.rm=TRUE)/nrow(sub),
                   unknown_pct=100*mean(is.na(sub$R)))
  }))
}))
readr::write_csv(d_dat,file.path(OUT,'s1d_fusion_thresholds.csv'))
p_d <- ggplot2::ggplot(d_dat,ggplot2::aes(quantile*100,confirmed_pct,color=nutrient,group=nutrient))+
  ggplot2::geom_line(linewidth=.85)+ggplot2::geom_point(size=2.1)+
  ggplot2::geom_text(ggplot2::aes(label=paste0('n=',n_retained)),
                     vjust=-.85,size=2.7,show.legend=FALSE)+
  ggplot2::scale_color_manual(values=COLORS)+
  ggplot2::scale_x_continuous(breaks=QS*100,labels=paste0(QS*100,'th'))+
  ggplot2::scale_y_continuous(expand=ggplot2::expansion(mult=c(.05,.18)))+
  ggplot2::labs(title='(d) Fusion edge-weight threshold sensitivity',
                subtitle='Confirmed physical support; not independent validation',
                x='Percentile of positive Fusion weights',
                y='Confirmed physically supported edges (%)',color=NULL)

base_theme <- ggplot2::theme_bw(base_size=10)+ggplot2::theme(
  panel.grid.minor=ggplot2::element_blank(),
  plot.title=ggplot2::element_text(face='bold',size=11),
  plot.subtitle=ggplot2::element_text(color='#606B75',size=8),
  strip.background=ggplot2::element_rect(fill='#F1F3F4',colour='#C7CED4'),
  legend.position='bottom')
p_a<-p_a+base_theme; p_b<-p_b+base_theme
p_c<-p_c+base_theme; p_d<-p_d+base_theme
fig <- (p_a | p_b) / (p_c | p_d) +
  patchwork::plot_annotation(
    title='Figure S1 | Robustness of Physical and Information Networks',
    subtitle='2011–2023 full-period networks | Raw p-value screening | Unresolved physical status retained',
    caption='Confirmed reachability is a lower bound; unknown is not non-reachable. Fusion threshold trends describe network composition, not independent physical validation.',
    theme=ggplot2::theme(plot.title=ggplot2::element_text(face='bold',size=16)))

ggplot2::ggsave(file.path(OUT,'Figure_S1_fullperiod.pdf'),fig,width=15,height=10.5,bg='white')
ggplot2::ggsave(file.path(OUT,'Figure_S1_fullperiod.png'),fig,width=15,height=10.5,dpi=350,bg='white')
for (i in seq_along(list(p_a,p_b,p_c,p_d)))
  ggplot2::ggsave(file.path(OUT,paste0('Figure_S1_',letters[i],'.pdf')),
                  list(p_a,p_b,p_c,p_d)[[i]],width=7.5,height=5,bg='white')
cat('\nFigure S1 complete. Output: ',OUT,'\n',sep='')
